import { z } from 'zod';

export const RUNTIME_TOOL_VERSION = 2;
const TaskId = z.string().regex(/^[A-Za-z0-9_.-]{1,200}$/);
export const Hi3dModelSource = z.object({
  provider: z.literal('hi3d'), taskId: TaskId, retryRootId: TaskId,
  jobPath: z.string().min(1), kind: z.enum(['model', 'relief', 'split', 'multicolor']),
  environment: z.enum(['test', 'pre', 'prod']), ownerId: z.string().min(1),
});
export type Hi3dModelSource = z.infer<typeof Hi3dModelSource>;

export const RetryDeliveryState = z.enum(['pending', 'sending', 'uncertain', 'accepted', 'rejected', 'cancelled']);
export const ModelRetry = z.object({
  requestId: z.string().uuid(), clientRequestId: z.string().min(1).max(200),
  assetId: z.string(), threadId: z.string(), fileName: z.string(), text: z.string(),
  source: Hi3dModelSource, deliveryState: RetryDeliveryState,
  executionState: z.enum(['pending', 'running', 'interrupted', 'submission_uncertain', 'completed', 'failed']),
  jobPath: z.string(), outputDir: z.string(), registerName: z.string(),
  tag4: z.enum(['humanoid', 'humanoid-base', 'statue', 'figurine', 'relief', 'sword', 'gun', 'general-prop']).nullable(),
  taskId: TaskId.optional(), registeredFileName: z.string().optional(),
  turnId: z.string().optional(), trackingId: z.string().optional(),
  createdAt: z.number(), updatedAt: z.number(),
});
export type ModelRetry = z.infer<typeof ModelRetry>;

export const RetryQuota = z.object({
  assetId: z.string(), fileName: z.string(), retryRootId: z.string().optional(),
  supported: z.boolean(), state: z.enum(['ready', 'unknown', 'unavailable']),
  remaining: z.number().int().nonnegative().nullable(), eligible: z.boolean(), can_retry: z.boolean(),
  updatedAt: z.number(),
});
export type RetryQuota = z.infer<typeof RetryQuota>;

export const modelRetryMethods = {
  'model/retry.request': {
    params: z.object({ clientRequestId: z.string().uuid(), assetId: z.string(), fileName: z.string().min(1),
      locale: z.enum(['en', 'zh', 'ja', 'de', 'es', 'fr', 'id', 'ko', 'pt', 'uk']).optional() }).strict(),
    result: ModelRetry,
  },
  'model/retry.list': {
    params: z.object({ assetId: z.string() }).strict(), result: z.object({ retries: z.array(ModelRetry) }),
  },
  'model/retry.cancelPending': {
    params: z.object({ assetId: z.string(), requestId: z.string().uuid() }).strict(), result: ModelRetry,
  },
  'model/retryQuota.read': {
    params: z.object({ assetId: z.string(), fileName: z.string().min(1), refresh: z.boolean().optional() }).strict(), result: RetryQuota,
  },
} as const;
